<script setup lang="ts">
import { ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { useRouter } from 'vue-router'
import { tokenStorage } from '@/api/client'
import { researchApi,type Hit,type SavedSearch } from '@/api/research'
import { authStore } from '@/stores/auth'
import { createRequestGuard } from '@/lib/requestGuard'
import SearchHighlight from '@/components/SearchHighlight.vue'
const router=useRouter(), dialog=ref<HTMLDialogElement|null>(null), searchInput=ref<HTMLInputElement|null>(null)
const query=ref(''),appliedQuery=ref(''),hits=ref<Hit[]>([]),saved=ref<SavedSearch[]>([]),active=ref(-1),error=ref(''),loading=ref(false),notifications=ref<Awaited<ReturnType<typeof researchApi.notifications>>>([])
const searchGuard=createRequestGuard(),savedGuard=createRequestGuard()
let debounce:ReturnType<typeof setTimeout>|undefined, retry:ReturnType<typeof setTimeout>|undefined, poll:ReturnType<typeof setInterval>|undefined,stream:AbortController|undefined,disposed=false,refreshing=false
async function open(){if(!authStore.has('research:use'))return;if(dialog.value?.open){searchInput.value?.focus();return}dialog.value?.showModal();await nextTick();searchInput.value?.focus();void search();const request=savedGuard.start();try{const rows=await researchApi.savedSearches(request.signal);if(request.current())saved.value=rows}catch{/* Search remains available if shortcuts cannot load. */}}
function close(){searchGuard.cancel();savedGuard.cancel();clearTimeout(debounce);loading.value=false;dialog.value?.close()}
function backdrop(e:MouseEvent){if(e.target!==dialog.value||!dialog.value)return;const b=dialog.value.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)close()}
function key(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!e.isComposing){if(!authStore.has('research:use'))return;e.preventDefault();void open()}}
function navigate(e:KeyboardEvent){if(e.isComposing)return;if(e.key==='Escape'){e.preventDefault();close();return}if(!hits.value.length||loading.value)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active.value=(active.value+(e.key==='ArrowDown'?1:-1)+hits.value.length)%hits.value.length;void nextTick(()=>dialog.value?.querySelector('#command-hit-'+active.value)?.scrollIntoView?.({block:'nearest'}))}else if(e.key==='Enter'&&active.value>=0){e.preventDefault();const hit=hits.value[active.value];if(hit)go(sourcePath(hit))}}
const sourcePath=(hit:Hit)=>'/app/research?tab=search&type='+encodeURIComponent(hit.kind)+'&source='+encodeURIComponent(hit.id)
function useSaved(row:SavedSearch){const params=new URLSearchParams({tab:'search',q:row.filters.q,type:row.filters.type,tag:row.filters.tag,sort:row.filters.sort});if(row.filters.since)params.set('since',row.filters.since.slice(0,10));if(row.filters.group)params.set('group',String(row.filters.group));go('/app/research?'+params)}
async function search(){if(!dialog.value?.open)return;const request=searchGuard.start(),text=query.value;loading.value=true;error.value='';active.value=-1;try{const result=await researchApi.search({q:text,page:'0'},request.signal);if(request.current()){hits.value=result.items;appliedQuery.value=text;active.value=result.items.length?0:-1}}catch(e){if(request.current()){hits.value=[];error.value=(e as Error).message}}finally{if(request.current())loading.value=false}}
function go(path:string){close();void router.push(path)}
watch(query,()=>{searchGuard.cancel();active.value=-1;clearTimeout(debounce);if(dialog.value?.open){loading.value=true;debounce=setTimeout(search,250)}})
async function refresh(){if(refreshing||disposed)return;refreshing=true;try{const rows=await researchApi.notifications();if(!disposed)notifications.value=rows}catch{/* The request client handles session expiry. */}finally{refreshing=false}}
async function connect(){
 if(disposed||!authStore.state.user)return
 const generation=tokenStorage.generation();stream=new AbortController()
 try{
  const response=await fetch((import.meta.env.VITE_API_BASE_URL||'/api/v1')+'/notifications/events',{headers:{Authorization:`Bearer ${tokenStorage.get()}`},signal:stream.signal,cache:'no-store'})
  if(!response.ok||!response.body)throw new Error('Live updates unavailable')
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer=''
  while(!disposed&&generation===tokenStorage.generation()){
   const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true}).replace(/\r\n/g,'\n')
   let end:number;while((end=buffer.indexOf('\n\n'))>=0){const event=buffer.slice(0,end);buffer=buffer.slice(end+2);if(event.includes('event:refresh')){void refresh();window.dispatchEvent(new Event('pkb:live-update'))}}
  }
  await reader.cancel()
 }catch{/* Retry on a bounded delay. The 30-second refresh also covers a missed reconnect event. */}
 finally{if(!disposed)retry=setTimeout(connect,2000)}
}
onMounted(()=>{window.addEventListener('keydown',key);void refresh();void connect();poll=setInterval(refresh,30000)})
onBeforeUnmount(()=>{disposed=true;searchGuard.cancel();savedGuard.cancel();stream?.abort();clearTimeout(debounce);clearTimeout(retry);clearInterval(poll);window.removeEventListener('keydown',key)})
</script>
<template>
 <button v-if="authStore.has('research:use')" class="workspace-search-button" @click="open">搜索 <kbd>Ctrl K</kbd></button>
 <details class="notification-menu"><summary>通知 <span v-if="notifications.length">{{ notifications.reduce((sum,n)=>sum+n.count,0) }}</span></summary><div class="notification-list"><strong>通知中心</strong><p v-if="!notifications.length">暂时没有未读消息</p><button v-for="n in notifications" :key="n.id" @click="go(n.url)">{{ n.title }} <small>{{ n.count }}</small></button><RouterLink to="/app/research?tab=cards">查看到期复习卡 →</RouterLink></div></details>
 <dialog ref="dialog" class="command-dialog" aria-label="全局搜索" @click="backdrop" @cancel.prevent="close" @close="searchGuard.cancel();savedGuard.cancel()"><div class="command-head"><input ref="searchInput" v-model="query" role="combobox" aria-controls="command-results" :aria-expanded="true" :aria-activedescendant="active>=0?'command-hit-'+active:undefined" autocomplete="off" maxlength="160" placeholder="搜索笔记、资料、图片识别结果…" aria-label="全局搜索" @keydown="navigate"/><button @click="close" aria-label="关闭搜索">Esc</button></div><div v-if="saved.length&&!query" class="command-shortcuts"><span>常用搜索</span><button v-for="row in saved.slice(0,6)" :key="row.id" @click="useSaved(row)">{{ row.name }}</button></div><p v-if="error" role="alert">{{ error }}</p><p v-if="loading" role="status">正在搜索…</p><div id="command-results" class="command-results" role="listbox" aria-label="搜索结果" :aria-busy="loading"><button v-for="(h,index) in hits" :id="'command-hit-'+index" :key="h.kind+h.id" role="option" :aria-label="h.title" :aria-selected="index===active&&!loading" :disabled="loading" @mouseenter="active=index" @click="go(sourcePath(h))"><small>{{ h.kind }}</small><strong><SearchHighlight :text="h.title" :query="appliedQuery"/></strong><span><SearchHighlight :text="h.excerpt" :query="appliedQuery"/></span></button><p v-if="!loading&&!hits.length">没有找到可访问的资料。</p></div><footer><span>↑↓ 选择 · Enter 打开</span><button @click="go('/app/research?tab=bookmarks')">我的收藏</button><button @click="go('/app/research?tab=search&q='+encodeURIComponent(query))">全部结果与筛选 →</button></footer></dialog>
</template>
<style scoped>
.command-shortcuts{display:flex;flex-wrap:wrap;gap:8px;padding:14px 24px;border-bottom:1px solid var(--line);font-size:12px}.command-shortcuts>span{color:var(--muted);padding:5px}.command-shortcuts button{border:1px solid var(--line);border-radius:4px;background:none;color:var(--green);padding:5px 9px;cursor:pointer}.command-results>button[aria-selected="true"]{background:var(--code-paper)}.command-results>button:disabled{opacity:.45;cursor:wait}.command-dialog footer{display:flex;gap:20px;align-items:center;justify-content:flex-end}.command-dialog footer>span{margin-right:auto;color:var(--muted);font-size:11px}.command-head input:focus-visible{outline:2px solid var(--green);outline-offset:6px;border-radius:2px}.command-dialog button:focus-visible{outline:2px solid var(--green);outline-offset:-2px}
.workspace-search-button,.notification-menu summary{background:none;border:0;color:var(--ink);font-size:13px;padding:8px 12px;cursor:pointer}.workspace-search-button kbd{color:var(--muted);margin-left:10px;font-size:11px}.notification-menu{position:relative}.notification-list{position:absolute;right:0;top:40px;z-index:80;width:320px;max-height:450px;overflow:auto;background:var(--paper);border:1px solid var(--line);padding:20px;box-shadow:0 12px 30px #20304015}.notification-list button{display:flex;width:100%;padding:12px 0;border:0;border-bottom:1px solid var(--line);background:none;text-align:left;justify-content:space-between;cursor:pointer;color:var(--ink)}.notification-list p,.notification-list a{font-size:13px;color:var(--muted)}.command-dialog{width:min(720px,90vw);margin:12vh auto;border:1px solid var(--line);border-radius:6px;padding:0;color:var(--ink);background:var(--paper);box-shadow:0 28px 90px #15202c25}.command-dialog::backdrop{background:#14223355}.command-head{display:flex;gap:16px;padding:20px;border-bottom:1px solid var(--line)}.command-head input{flex:1;border:0;outline:0;background:none;color:inherit;font-size:17px}.command-head button,.command-dialog footer button{background:none;border:0;color:var(--green);cursor:pointer}.command-results{max-height:52vh;overflow:auto}.command-results>button{display:grid;grid-template-columns:70px 1fr;gap:5px 12px;text-align:left;width:100%;border:0;background:none;padding:16px 24px;border-bottom:1px solid var(--line);color:var(--ink);cursor:pointer}.command-results>button:hover,.command-results>button:focus-visible{background:var(--code-paper)}.command-results small{grid-row:span 2;color:var(--muted);font-size:10px}.command-results span{font-size:13px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.command-results p,.command-dialog>p{padding:20px}.command-dialog footer{padding:14px 24px}
</style>
